const httpJson = $input.first().json;
let csvRaw = httpJson.data ?? httpJson.body ?? httpJson.text ?? '';
if (typeof csvRaw !== 'string') {
  if (csvRaw && typeof csvRaw === 'object') csvRaw = csvRaw.data ?? csvRaw.body ?? JSON.stringify(csvRaw);
  else csvRaw = String(csvRaw || '');
}
const text = csvRaw;

const lines = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
const headers = (lines[0] || 'perfil,produto,minimo,rentabilidade').split(',').map((h) => h.trim());

const investimentos = lines.slice(1).map((line) => {
  const cols = line.split(',').map((c) => c.trim());
  const obj = {};
  headers.forEach((h, i) => { obj[h] = cols[i] ?? ''; });
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, '')) || 0;
  return obj;
});

let clientes = [];
try {
  const wh = $('Webhook - Clientes').first().json;
  clientes = wh.body?.clientes ?? wh.query?.clientes ?? wh.clientes ?? wh.body ?? [];
  if (!Array.isArray(clientes)) clientes = [clientes];
  if (typeof clientes[0] === 'string') { try { clientes = JSON.parse(clientes[0]); } catch(e) {} }
} catch(e) {}

return [{ json: { clientes, investimentos } }];

const raw = $input.item.json;
const item = (raw.clientes && typeof raw.clientes === 'object' && !Array.isArray(raw.clientes)) ? { ...raw, ...raw.clientes } : raw;
let investimentos = item.investimentos ?? [];
try { if ((!investimentos || investimentos.length === 0)) investimentos = $('Parse CSV').first().json.investimentos ?? []; } catch(e) {}

function parseSaldo(s) {
  if (s == null) return 0;
  const clean = String(s).replace(/R\$|\s/g, '').replace(/\./g, '').replace(',', '.').replace(/[^\d.]/g, '');
  return parseFloat(clean) || 0;
}
function parseRent(r) {
  const n = parseFloat(String(r).replace(/[^\d.,]/g, '').replace(',', '.'));
  return isNaN(n) ? 0 : n;
}

const perfil = (item.perfil || '').trim();
const saldoNum = parseSaldo(item.saldo);
const opcoes = investimentos.filter((inv) => (inv.perfil || '').toLowerCase().trim() === perfil.toLowerCase());
const elegiveis = opcoes.filter((inv) => saldoNum >= (inv.minimo || 0));

let escolhido = null;
let motivo = 'sem_opcao';
if (elegiveis.length > 0) {
  escolhido = elegiveis.reduce((a, b) => (parseRent(b.rentabilidade) > parseRent(a.rentabilidade) ? b : a));
  motivo = 'saldo_ok';
} else if (opcoes.length > 0) {
  escolhido = opcoes.reduce((a, b) => ((b.minimo || 0) < (a.minimo || 0) ? b : a));
  motivo = 'saldo_insuficiente';
}

return {
  nome: item.nome,
  email: item.email,
  saldo: item.saldo,
  saldo_num: saldoNum,
  perfil: perfil,
  produto_recomendado: escolhido?.produto ?? '',
  rentabilidade: escolhido?.rentabilidade ?? '',
  minimo: escolhido?.minimo ?? 0,
  motivo: motivo
};
